package app

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

const (
	ExitOK         = 0
	ExitError      = 1
	ExitUsage      = 2
	ExitConfig     = 3
	ExitWorkspace  = 4
	ExitValidation = 5
	ExitRuntime    = 6
	ExitCancel     = 7
	ExitPartial    = 8
)

type Config struct {
	Args                 []string
	Stdin                io.Reader
	Stdout               io.Writer
	Stderr               io.Writer
	Context              context.Context
	Version              Version
	WorkDir              string
	Env                  map[string]string
	TUIRunner            TUIRunner
	WebRunner            WebRunner
	SprintRuntimeFactory SprintRuntimeFactory
}

type classedError struct {
	class int
	code  string
	err   error
}

func (e classedError) Error() string { return e.err.Error() }
func (e classedError) Unwrap() error { return e.err }
func (e classedError) Code() string  { return e.code }

type displayError struct {
	display string
	cause   error
}

func (e displayError) Error() string { return e.display }
func (e displayError) Unwrap() error { return e.cause }

func classified(class int, format string, args ...any) error {
	return classedError{class: class, code: errorCode(class), err: fmt.Errorf(format, args...)}
}

func classifiedCause(class int, cause error, format string, args ...any) error {
	return classedError{class: class, code: errorCode(class), err: fmt.Errorf(format+": %w", append(args, cause)...)}
}

func errorCode(class int) string {
	switch class {
	case ExitUsage:
		return "validation.usage"
	case ExitConfig:
		return "config.invalid"
	case ExitWorkspace:
		return "validation.workspace"
	case ExitValidation:
		return "validation.reference"
	case ExitRuntime:
		return "provider.runtime"
	case ExitCancel:
		return "workflow.cancelled"
	case ExitPartial:
		return "workflow.partial"
	default:
		return "internal.error"
	}
}

func Run(cfg Config) int {
	stdout := cfg.Stdout
	if stdout == nil {
		stdout = io.Discard
	}

	stderr := cfg.Stderr
	if stderr == nil {
		stderr = io.Discard
	}
	stdin := cfg.Stdin
	if stdin == nil {
		stdin = os.Stdin
	}

	version := cfg.Version
	if version.IsZero() {
		version = DefaultVersion()
	}

	runControl := newRunControlState()
	defer runControl.Close()
	deps := dependencies{
		stdout:               stdout,
		stderr:               stderr,
		stdin:                stdin,
		ctx:                  cfg.Context,
		workDir:              cfg.WorkDir,
		env:                  cfg.Env,
		tuiRunner:            cfg.TUIRunner,
		webRunner:            cfg.WebRunner,
		sprintRuntimeFactory: cfg.SprintRuntimeFactory,
		runControl:           runControl,
	}
	if deps.sprintRuntimeFactory == nil {
		deps.sprintRuntimeFactory = defaultSprintRuntimeFactory
	}
	if deps.ctx == nil {
		deps.ctx = context.Background()
	}
	if deps.workDir == "" {
		if wd, err := os.Getwd(); err == nil {
			deps.workDir = wd
		}
	}

	args, global, err := parseGlobalFlags(cfg.Args)
	if err != nil {
		return fail(stderr, classified(ExitUsage, "parse global flags: %w", err))
	}
	deps.workspaceFlag = global.workspace

	if len(args) == 0 {
		return writeStatus(stdout, renderHelp())
	}

	switch args[0] {
	case "--help", "-h":
		return writeStatus(stdout, renderHelp())
	case "version":
		return writeStatus(stdout, renderVersion(version))
	case "init-workspace":
		return failOrOK(stderr, runInitWorkspace(deps, args[1:]))
	case "defaults":
		return failOrOK(stderr, runDefaults(deps, args[1:]))
	case "skills":
		return failOrOK(stderr, runSkills(deps, args[1:]))
	case "config":
		return failOrOK(stderr, runConfig(deps, args[1:]))
	case "health":
		return failOrOK(stderr, runHealth(deps, args[1:]))
	case "storage":
		return failOrOK(stderr, runStorage(deps, args[1:]))
	case "run":
		return failOrOK(stderr, runRun(deps, args[1:]))
	case "project":
		return failOrOK(stderr, runProject(deps, args[1:]))
	case "sprint":
		return failOrOK(stderr, runSprint(deps, args[1:]))
	case "study":
		return failOrOK(stderr, runStudy(deps, args[1:]))
	case "tui":
		return failOrOK(stderr, runTUI(deps, args[1:]))
	case "serve":
		return failOrOK(stderr, runServe(deps, args[1:]))
	case "code":
		return failOrOK(stderr, runCode(deps, args[1:]))
	default:
		return fail(stderr, classified(ExitUsage, "unknown command %q\n\nRun 'ultraplan --help' to see available commands.", args[0]))
	}
}

type dependencies struct {
	stdout               io.Writer
	stderr               io.Writer
	stdin                io.Reader
	ctx                  context.Context
	workDir              string
	workspaceFlag        string
	env                  map[string]string
	tuiRunner            TUIRunner
	webRunner            WebRunner
	sprintRuntimeFactory SprintRuntimeFactory
	runControl           *runControlState
}

type globalFlags struct {
	workspace string
}

func parseGlobalFlags(args []string) ([]string, globalFlags, error) {
	var out []string
	var flags globalFlags
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--workspace":
			if i+1 >= len(args) || strings.HasPrefix(args[i+1], "-") {
				return nil, flags, errors.New("--workspace requires a path")
			}
			flags.workspace = args[i+1]
			i++
		case strings.HasPrefix(arg, "--workspace="):
			flags.workspace = strings.TrimPrefix(arg, "--workspace=")
			if flags.workspace == "" {
				return nil, flags, errors.New("--workspace requires a path")
			}
		default:
			out = append(out, arg)
		}
	}
	return out, flags, nil
}

func failOrOK(stderr io.Writer, err error) int {
	if err == nil {
		return ExitOK
	}
	return fail(stderr, err)
}

func fail(stderr io.Writer, err error) int {
	if err == nil {
		return ExitOK
	}
	if _, writeErr := fmt.Fprintln(stderr, err.Error()); writeErr != nil {
		return ExitError
	}
	var classifiedErr classedError
	if errors.As(err, &classifiedErr) {
		return classifiedErr.class
	}
	return ExitError
}

func writeStatus(w io.Writer, text string) int {
	if _, err := io.WriteString(w, text); err != nil {
		return ExitError
	}
	return ExitOK
}

func renderHelp() string {
	return `ultraplan

Usage:
  ultraplan [--workspace <path>] [command]

Commands:
  init-workspace   Initialize an UltraPlan workspace.
  defaults         Install editable built-in prompts and templates.
  skills           Materialise manually invoked stage skills.
  config           Inspect effective configuration.
  storage          Migrate mutable product state into SQLite.
  code             Extract cited code snippets from reports.
  health           Check workspace, config, filesystem, and environment basics.
  run              Inspect, follow, cancel, and diagnose durable runs.
  project          Inspect projects and validate project indexes.
  sprint           Inspect planning sprint artifact flow state.
  study            Inspect studies, sources, and dimensions.
  tui              Open a read-only terminal dashboard.
  serve            Start the read-only local browser dashboard.
  version          Print build metadata.

Flags:
  --workspace <path>   Use a workspace path.
  -h, --help          Show help.
`
}

func renderVersion(version Version) string {
	return fmt.Sprintf("Version: %s\nCommit: %s\nBuildDate: %s\nGoVersion: %s\n",
		version.Version,
		version.Commit,
		version.BuildDate,
		version.GoVersion,
	)
}

func discoverWorkspace(deps dependencies) (workspace.Root, error) {
	env := envLookup(deps.env)
	root, err := workspace.Discover(workspace.DiscoverOptions{
		ExplicitPath: deps.workspaceFlag,
		EnvWorkspace: env("ULTRAPLAN_WORKSPACE"),
		StartDir:     deps.workDir,
	})
	if err != nil {
		return workspace.Root{}, classified(ExitWorkspace, "workspace.discover: %w", err)
	}
	return root, nil
}

func envLookup(env map[string]string) func(string) string {
	return func(key string) string {
		if env != nil {
			return env[key]
		}
		return os.Getenv(key)
	}
}

func loadEffectiveConfig(root workspace.Root, deps dependencies, cli config.CLIOverrides) (config.Effective, error) {
	effective, err := config.Load(config.LoadOptions{
		WorkspaceRoot: root.Path,
		Env:           envLookup(deps.env),
		CLI:           cli,
	})
	if err != nil {
		return config.Effective{}, classified(ExitConfig, "config.load: %w", err)
	}
	return effective, nil
}

package app

import (
	"context"
	"fmt"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type healthCheck struct {
	ID       string `json:"id"`
	Name     string `json:"name"`
	Status   string `json:"status"`
	Message  string `json:"message,omitempty"`
	Guidance string `json:"guidance,omitempty"`
}

type healthResult struct {
	SchemaVersion int           `json:"schema_version"`
	Runtime       string        `json:"runtime,omitempty"`
	Workspace     string        `json:"workspace,omitempty"`
	Config        string        `json:"config,omitempty"`
	Checks        []healthCheck `json:"checks"`
}

var runtimeHealthChecks = runRuntimeHealth

func runHealth(deps dependencies, args []string) error {
	jsonOut := false
	for _, arg := range args {
		switch arg {
		case "--help", "-h":
			_, err := deps.stdout.Write([]byte(healthHelp()))
			return err
		case "--json":
			jsonOut = true
		default:
			return classified(ExitUsage, "health: unknown argument %q", arg)
		}
	}
	var checks []healthCheck
	root, err := discoverWorkspace(deps)
	if err != nil {
		checks = append(checks, healthCheck{ID: "workspace.discovery", Name: "workspace.discovery", Status: "fail", Message: config.RedactValue("workspace.error", err.Error()), Guidance: "run from an UltraPlan workspace or pass --workspace"})
		if jsonOut {
			_ = writeJSON(deps.stdout, "health", "", "fail", healthResult{SchemaVersion: 1, Checks: checks})
		}
		return err
	}
	checks = append(checks, healthCheck{ID: "workspace.discovery", Name: "workspace.discovery", Status: "ok", Message: workspace.Rel(root.Path, root.Path)})
	validation := workspace.Validate(root.Path)
	if validation.Valid {
		checks = append(checks, healthCheck{ID: "workspace.structure", Name: "workspace.structure", Status: "ok"})
	} else {
		checks = append(checks, healthCheck{ID: "workspace.structure", Name: "workspace.structure", Status: "fail", Message: config.RedactValue("workspace.structure", validation.Issues[0]), Guidance: "run 'ultraplan init-workspace' or restore required workspace files"})
	}
	effective, cfgErr := loadEffectiveConfig(root, deps, config.CLIOverrides{JSON: jsonOut})
	if cfgErr == nil {
		checks = append(checks, healthCheck{ID: "config.validation", Name: "config.validation", Status: "ok"})
	} else {
		checks = append(checks, healthCheck{ID: "config.validation", Name: "config.validation", Status: "fail", Message: config.RedactValue("config.error", cfgErr.Error()), Guidance: "fix ultraplan.yml or CLI overrides"})
	}
	checks = append(checks, healthCheck{ID: "filesystem.read", Name: "filesystem.read", Status: "ok", Message: workspace.MarkerFile})
	checks = append(checks, healthCheck{ID: "environment.overrides", Name: "environment.overrides", Status: "ok", Message: envSummary(deps)})
	runtimeFailed := false
	if cfgErr == nil {
		runtimeChecks, err := runtimeHealthChecks(deps.ctx, root.Path, effective.Config)
		checks = append(checks, sanitizeHealthChecks(runtimeChecks)...)
		if err != nil {
			runtimeFailed = true
		}
	}
	result := healthResult{SchemaVersion: 1, Workspace: root.Path, Checks: checks}
	if cfgErr == nil {
		result.Runtime = effective.Config.Runtime.Default
		result.Config = "valid"
	} else {
		result.Config = "invalid"
	}
	status := "ok"
	if !validation.Valid || cfgErr != nil || runtimeFailed {
		status = "fail"
	}
	if jsonOut {
		if err := writeJSON(deps.stdout, "health", root.Path, status, result); err != nil {
			return err
		}
	} else {
		fmt.Fprintf(deps.stdout, "Workspace: %s\n", root.Path)
		for _, check := range checks {
			if check.Message == "" {
				fmt.Fprintf(deps.stdout, "%s: %s\n", check.Name, check.Status)
			} else {
				fmt.Fprintf(deps.stdout, "%s: %s - %s\n", check.Name, check.Status, check.Message)
			}
		}
	}
	if cfgErr != nil {
		return cfgErr
	}
	if runtimeFailed {
		return classified(ExitRuntime, "runtime.health: one or more runtime checks failed")
	}
	if !validation.Valid {
		return classified(ExitValidation, "workspace.validate: %s", validation.Issues[0])
	}
	return nil
}

func runRuntimeHealth(ctx context.Context, workDir string, c config.Config) ([]healthCheck, error) {
	adapter, err := runtimepkg.NewOpenCode(c)
	if err != nil {
		return []healthCheck{{ID: "runtime.opencode", Name: "runtime.opencode", Status: "fail", Message: config.RedactValue("runtime.error", err.Error()), Guidance: "check runtime executable and agentwrap configuration"}}, err
	}
	req, err := runtimepkg.RequestFromConfig(c, workDir)
	if err != nil {
		return []healthCheck{{ID: "runtime.opencode", Name: "runtime.opencode", Status: "fail", Message: config.RedactValue("runtime.error", err.Error()), Guidance: "check runtime configuration"}}, err
	}
	report, err := adapter.Health(ctx, runtimepkg.HealthRequest{
		WorkDir:        workDir,
		Provider:       req.Provider,
		Model:          req.Model,
		Checks:         req.RequireHealth,
		RequiredChecks: req.RequireHealth,
		Capabilities:   req.RequireCaps,
	})
	checks := make([]healthCheck, 0, len(report.Checks)+len(report.Capabilities))
	for _, check := range report.Checks {
		id := "runtime." + check.Name
		checks = append(checks, healthCheck{ID: id, Name: id, Status: check.Status, Message: config.RedactValue(id, check.Message), Guidance: runtimeGuidance(check.Status)})
	}
	for _, cap := range report.Capabilities {
		status := "ok"
		if !cap.Supported {
			status = "fail"
		}
		id := "runtime.capability." + cap.Name
		checks = append(checks, healthCheck{ID: id, Name: id, Status: status, Message: config.RedactValue(id, cap.Message), Guidance: runtimeGuidance(status)})
	}
	if err != nil {
		if len(checks) == 0 {
			checks = append(checks, healthCheck{ID: "runtime.opencode", Name: "runtime.opencode", Status: "fail", Message: config.RedactValue("runtime.error", err.Error()), Guidance: "check runtime executable and provider configuration"})
		}
		return checks, err
	}
	return checks, nil
}

func runtimeGuidance(status string) string {
	if status == "ok" {
		return ""
	}
	return "check runtime executable, provider configuration, and required capabilities"
}

func sanitizeHealthChecks(checks []healthCheck) []healthCheck {
	out := append([]healthCheck(nil), checks...)
	for i := range out {
		if out[i].ID == "" {
			out[i].ID = out[i].Name
		}
		if out[i].Name == "" {
			out[i].Name = out[i].ID
		}
		out[i].Message = config.RedactValue(out[i].ID, out[i].Message)
		out[i].Guidance = config.RedactValue(out[i].ID+".guidance", out[i].Guidance)
		if out[i].Guidance == "" {
			out[i].Guidance = runtimeGuidance(out[i].Status)
		}
	}
	return out
}

func envSummary(deps dependencies) string {
	env := envLookup(deps.env)
	count := 0
	keys := []string{"ULTRAPLAN_WORKSPACE"}
	for _, override := range config.EnvOverrides() {
		keys = append(keys, override.Key)
	}
	for _, key := range keys {
		if env(key) != "" {
			count++
		}
	}
	return fmt.Sprintf("%d ULTRAPLAN_ override(s) present", count)
}

func healthHelp() string {
	return `ultraplan health

Usage:
  ultraplan health [--json]

Flags:
  --json      Print JSON output.
  -h, --help  Show help.
`
}

